"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2416],{20252:t=>{t.exports=JSON.parse('{"functions":[{"name":"CreateWeld","desc":"Welds `part1` to `part0` so that `attachment1` lines up with `attachment0`.\\n\\nThe Motor6D is named `Weld_<part0>_<part1>` and parented to `part0`; destroy it\\nto break the joint.\\n\\n```lua\\nlocal motor = CreateWeld({\\n\\tpart0 = character[\\"Right Arm\\"],\\n\\tpart1 = tool.Handle,\\n\\tattachment0 = character[\\"Right Arm\\"].RightGripAttachment,\\n\\tattachment1 = tool.Handle.GripAttachment,\\n})\\n```","params":[{"name":"data","desc":"","lua_type":"{ part0: BasePart, part1: BasePart, attachment0: Attachment, attachment1: Attachment }"}],"returns":[{"desc":"","lua_type":"Motor6D"}],"function_type":"static","source":{"line":36,"path":"src/Shared/Modules/CreateWeld.luau"}}],"properties":[],"types":[],"name":"CreateWeld","desc":"Creates a [Motor6D] weld between two parts, aligning them based on the provided\\nattachments.\\n\\nMotor6D is used rather than a plain Weld so the joint can be driven by an\\n[Animator]. For rigs built on AvatarJointUpgrade see [CreateCharacterWeld],\\nwhich produces an [AnimationConstraint] instead.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":14,"path":"src/Shared/Modules/CreateWeld.luau"}}')}}]);